import{_ as i,c as u,a as n,b as c,d as t,w as p,e as a,r as o,o as d}from"./app-CXDlbpxe.js";const r={},k={class:"table-of-contents"};function v(m,s){const e=o("router-link"),l=o("RouteLink");return d(),u("div",null,[s[22]||(s[22]=n("h1",{id:"asm-字节码框架入门",tabindex:"-1"},[n("a",{class:"header-anchor",href:"#asm-字节码框架入门"},[n("span",null,"ASM 字节码框架入门")])],-1)),n("nav",k,[n("ul",null,[n("li",null,[t(e,{to:"#什么是-asm"},{default:p(()=>s[0]||(s[0]=[a("什么是 ASM？")])),_:1,__:[0]})]),n("li",null,[t(e,{to:"#核心架构-事件驱动-visitor-模式"},{default:p(()=>s[1]||(s[1]=[a("核心架构：事件驱动 + Visitor 模式")])),_:1,__:[1]}),n("ul",null,[n("li",null,[t(e,{to:"#_1-事件驱动"},{default:p(()=>s[2]||(s[2]=[a("1. 事件驱动")])),_:1,__:[2]})]),n("li",null,[t(e,{to:"#_2-visitor-模式"},{default:p(()=>s[3]||(s[3]=[a("2. Visitor 模式")])),_:1,__:[3]})])])]),n("li",null,[t(e,{to:"#核心-api-详解"},{default:p(()=>s[4]||(s[4]=[a("核心 API 详解")])),_:1,__:[4]}),n("ul",null,[n("li",null,[t(e,{to:"#classreader-——-读取字节码"},{default:p(()=>s[5]||(s[5]=[a("ClassReader —— 读取字节码")])),_:1,__:[5]})]),n("li",null,[t(e,{to:"#classvisitor-——-访问类结构"},{default:p(()=>s[6]||(s[6]=[a("ClassVisitor —— 访问类结构")])),_:1,__:[6]})]),n("li",null,[t(e,{to:"#classwriter-——-生成字节码"},{default:p(()=>s[7]||(s[7]=[a("ClassWriter —— 生成字节码")])),_:1,__:[7]})]),n("li",null,[t(e,{to:"#methodvisitor-——-访问方法体"},{default:p(()=>s[8]||(s[8]=[a("MethodVisitor —— 访问方法体")])),_:1,__:[8]})])])]),n("li",null,[t(e,{to:"#三种典型场景"},{default:p(()=>s[9]||(s[9]=[a("三种典型场景")])),_:1,__:[9]}),n("ul",null,[n("li",null,[t(e,{to:"#场景一-只读——提取类信息"},{default:p(()=>s[10]||(s[10]=[a("场景一：只读——提取类信息")])),_:1,__:[10]})]),n("li",null,[t(e,{to:"#场景二-修改——给类添加方法"},{default:p(()=>s[11]||(s[11]=[a("场景二：修改——给类添加方法")])),_:1,__:[11]})]),n("li",null,[t(e,{to:"#场景三-生成——从零创建类"},{default:p(()=>s[12]||(s[12]=[a("场景三：生成——从零创建类")])),_:1,__:[12]})])])]),n("li",null,[t(e,{to:"#深入-修改方法体中的字节码"},{default:p(()=>s[13]||(s[13]=[a("深入：修改方法体中的字节码")])),_:1,__:[13]}),n("ul",null,[n("li",null,[t(e,{to:"#经典例子-在方法入口和出口插入日志"},{default:p(()=>s[14]||(s[14]=[a("经典例子：在方法入口和出口插入日志")])),_:1,__:[14]})]),n("li",null,[t(e,{to:"#注意事项"},{default:p(()=>s[15]||(s[15]=[a("注意事项")])),_:1,__:[15]})])])]),n("li",null,[t(e,{to:"#asm-版本常量与兼容性"},{default:p(()=>s[16]||(s[16]=[a("ASM 版本常量与兼容性")])),_:1,__:[16]})]),n("li",null,[t(e,{to:"#框架中的-asm-应用"},{default:p(()=>s[17]||(s[17]=[a("框架中的 ASM 应用")])),_:1,__:[17]})]),n("li",null,[t(e,{to:"#总结"},{default:p(()=>s[18]||(s[18]=[a("总结")])),_:1,__:[18]})])])]),s[23]||(s[23]=c(`<h2 id="什么是-asm" tabindex="-1"><a class="header-anchor" href="#什么是-asm"><span>什么是 ASM？</span></a></h2><p>ASM 是一个轻量级的 Java 字节码操作框架。它能够直接以二进制形式读取、修改和生成 <code>.class</code> 文件，而无需依赖 <code>javac</code> 编译器。</p><p>它的核心定位是<strong>底层、快速、精简</strong>：</p><table><thead><tr><th>维度</th><th>说明</th></tr></thead><tbody><tr><td>定位</td><td>字节码级别的操作库，不依赖源码</td></tr><tr><td>性能</td><td>极快，采用事件驱动模型，解析时只做一次遍历</td></tr><tr><td>体积</td><td>核心 jar 仅约 100KB</td></tr><tr><td>学习曲线</td><td>陡峭——需要理解字节码指令、类文件结构</td></tr></tbody></table><p>同类工具对比：</p><table><thead><tr><th>工具</th><th>抽象层级</th><th>特点</th></tr></thead><tbody><tr><td><strong>ASM</strong></td><td>字节码指令级</td><td>最底层，性能最好，但需要直接操作指令</td></tr><tr><td><strong>ByteBuddy</strong></td><td>类型/方法级</td><td>在 ASM 之上提供了高层 API，更易用</td></tr><tr><td><strong>Javassist</strong></td><td>源码级</td><td>可以用类 Java 代码操作字节码，最易上手但性能较低</td></tr><tr><td><strong>CGLIB</strong></td><td>方法拦截级</td><td>专注代理生成，底层依赖 ASM</td></tr></tbody></table><blockquote><p>很多开发者不会直接写 ASM 代码，但他们使用的框架——Spring、MyBatis、Hibernate、Mockito、Lombok——底层几乎都依赖 ASM。</p></blockquote><h2 id="核心架构-事件驱动-visitor-模式" tabindex="-1"><a class="header-anchor" href="#核心架构-事件驱动-visitor-模式"><span>核心架构：事件驱动 + Visitor 模式</span></a></h2><p>ASM 的设计基于两个核心思想：</p><h3 id="_1-事件驱动" tabindex="-1"><a class="header-anchor" href="#_1-事件驱动"><span>1. 事件驱动</span></a></h3><p>ASM 把 <code>.class</code> 文件看作一个<strong>事件流</strong>。解析一个类时，ASM 按顺序触发一系列事件：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code><span class="line">visit()                        // 开始解析类</span>
<span class="line">  visitSource()                // 类来源信息</span>
<span class="line">  visitAnnotation()            // 类上的注解</span>
<span class="line">  visitField()                 // 字段 1</span>
<span class="line">    visitAnnotation()          // 字段 1 上的注解</span>
<span class="line">  visitField()                 // 字段 2</span>
<span class="line">  visitMethod()                // 方法 1</span>
<span class="line">    visitAnnotation()          // 方法 1 上的注解</span>
<span class="line">    visitCode()                // 方法 1 的字节码开始</span>
<span class="line">      visitFrame()             // 栈帧</span>
<span class="line">      visitInsn()              // 指令：aload_0</span>
<span class="line">      visitMethodInsn()        // 指令：invokevirtual</span>
<span class="line">      visitInsn()              // 指令：return</span>
<span class="line">    visitEnd()                 // 方法 1 的字节码结束</span>
<span class="line">  visitMethod()                // 方法 2</span>
<span class="line">  ...</span>
<span class="line">visitEnd()                     // 类解析完毕</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>每个方法调用就是一个&quot;事件&quot;，事件的顺序严格按照 JVM 类文件结构的定义来排列。</p><h3 id="_2-visitor-模式" tabindex="-1"><a class="header-anchor" href="#_2-visitor-模式"><span>2. Visitor 模式</span></a></h3><p>你不需要解析整个类文件，只需要<strong>实现一个访问者</strong>，在感兴趣的事件上写处理逻辑即可。ASM 提供了 <code>ClassVisitor</code> 和 <code>MethodVisitor</code> 两个核心抽象类，你只需要继承它们并重写相应的方法。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code><span class="line">ClassReader（读取器）──解析类文件──→ ClassVisitor（你写的逻辑）──→ ClassWriter（输出字节码）</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>这个链条中：</p><ul><li><code>ClassReader</code> 负责解析字节码，生成事件流</li><li><code>ClassVisitor</code>（你实现的）负责在事件上做处理——可以修改、过滤、增强</li><li><code>ClassWriter</code> 负责把处理后的结果重新编码为字节码</li></ul><p>当你只需要<strong>读取</strong>类信息时，不需要 <code>ClassWriter</code>；只需要<strong>修改</strong>时，三者串联；只需要<strong>生成</strong>新类时，直接从 <code>ClassVisitor</code> 开始，不需要 <code>ClassReader</code>。</p><h2 id="核心-api-详解" tabindex="-1"><a class="header-anchor" href="#核心-api-详解"><span>核心 API 详解</span></a></h2><h3 id="classreader-——-读取字节码" tabindex="-1"><a class="header-anchor" href="#classreader-——-读取字节码"><span>ClassReader —— 读取字节码</span></a></h3><p><code>ClassReader</code> 负责解析一个 <code>.class</code> 文件的内容，将其转换为事件流。它可以从多种来源构造：</p><div class="language-java line-numbers-mode" data-highlighter="prismjs" data-ext="java"><pre><code><span class="line"><span class="token comment">// 从字节数组</span></span>
<span class="line"><span class="token keyword">byte</span><span class="token punctuation">[</span><span class="token punctuation">]</span> classBytes <span class="token operator">=</span> <span class="token class-name">Files</span><span class="token punctuation">.</span><span class="token function">readAllBytes</span><span class="token punctuation">(</span><span class="token class-name">Path</span><span class="token punctuation">.</span><span class="token function">of</span><span class="token punctuation">(</span><span class="token string">&quot;MyClass.class&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token class-name">ClassReader</span> reader <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">ClassReader</span><span class="token punctuation">(</span>classBytes<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 从类名（从 classpath 加载）</span></span>
<span class="line"><span class="token class-name">ClassReader</span> reader <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">ClassReader</span><span class="token punctuation">(</span><span class="token string">&quot;com.example.MyClass&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 从输入流</span></span>
<span class="line"><span class="token class-name">ClassReader</span> reader <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">ClassReader</span><span class="token punctuation">(</span>inputStream<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>ClassReader</code> 的 <code>accept()</code> 方法接收一个 <code>ClassVisitor</code>，然后按顺序触发访问事件：</p><div class="language-java line-numbers-mode" data-highlighter="prismjs" data-ext="java"><pre><code><span class="line">reader<span class="token punctuation">.</span><span class="token function">accept</span><span class="token punctuation">(</span>myVisitor<span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>第二个参数是解析选项，常用值：</p><table><thead><tr><th>选项</th><th>含义</th></tr></thead><tbody><tr><td><code>0</code></td><td>默认行为</td></tr><tr><td><code>ClassReader.SKIP_DEBUG</code></td><td>跳过调试信息（行号表、局部变量表等），减小体积</td></tr><tr><td><code>ClassReader.SKIP_CODE</code></td><td>跳过方法体中的字节码，只读类结构</td></tr><tr><td><code>ClassReader.EXPAND_FRAMES</code></td><td>展开栈帧映射，默认展开</td></tr></tbody></table><h3 id="classvisitor-——-访问类结构" tabindex="-1"><a class="header-anchor" href="#classvisitor-——-访问类结构"><span>ClassVisitor —— 访问类结构</span></a></h3><p><code>ClassVisitor</code> 是一个抽象类，定义了访问类结构各个部分的方法。你需要继承它并重写需要处理的方法。</p><div class="language-java line-numbers-mode" data-highlighter="prismjs" data-ext="java"><pre><code><span class="line"><span class="token keyword">public</span> <span class="token keyword">abstract</span> <span class="token keyword">class</span> <span class="token class-name">ClassVisitor</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// 构造时传入下一个访问者，形成链式调用</span></span>
<span class="line">    <span class="token keyword">public</span> <span class="token class-name">ClassVisitor</span><span class="token punctuation">(</span><span class="token keyword">int</span> api<span class="token punctuation">,</span> <span class="token class-name">ClassVisitor</span> cv<span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">.</span> <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">public</span> <span class="token keyword">void</span> <span class="token function">visit</span><span class="token punctuation">(</span><span class="token keyword">int</span> version<span class="token punctuation">,</span> <span class="token keyword">int</span> access<span class="token punctuation">,</span> <span class="token class-name">String</span> name<span class="token punctuation">,</span></span>
<span class="line">                      <span class="token class-name">String</span> signature<span class="token punctuation">,</span> <span class="token class-name">String</span> superName<span class="token punctuation">,</span> <span class="token class-name">String</span><span class="token punctuation">[</span><span class="token punctuation">]</span> interfaces<span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">.</span> <span class="token punctuation">}</span></span>
<span class="line">    <span class="token keyword">public</span> <span class="token keyword">void</span> <span class="token function">visitSource</span><span class="token punctuation">(</span><span class="token class-name">String</span> source<span class="token punctuation">,</span> <span class="token class-name">String</span> debug<span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">.</span> <span class="token punctuation">}</span></span>
<span class="line">    <span class="token keyword">public</span> <span class="token class-name">AnnotationVisitor</span> <span class="token function">visitAnnotation</span><span class="token punctuation">(</span><span class="token class-name">String</span> desc<span class="token punctuation">,</span> <span class="token keyword">boolean</span> visible<span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">.</span> <span class="token punctuation">}</span></span>
<span class="line">    <span class="token keyword">public</span> <span class="token class-name">FieldVisitor</span> <span class="token function">visitField</span><span class="token punctuation">(</span><span class="token keyword">int</span> access<span class="token punctuation">,</span> <span class="token class-name">String</span> name<span class="token punctuation">,</span> <span class="token class-name">String</span> desc<span class="token punctuation">,</span></span>
<span class="line">                                   <span class="token class-name">String</span> signature<span class="token punctuation">,</span> <span class="token class-name">Object</span> value<span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">.</span> <span class="token punctuation">}</span></span>
<span class="line">    <span class="token keyword">public</span> <span class="token class-name">MethodVisitor</span> <span class="token function">visitMethod</span><span class="token punctuation">(</span><span class="token keyword">int</span> access<span class="token punctuation">,</span> <span class="token class-name">String</span> name<span class="token punctuation">,</span> <span class="token class-name">String</span> desc<span class="token punctuation">,</span></span>
<span class="line">                                     <span class="token class-name">String</span> signature<span class="token punctuation">,</span> <span class="token class-name">String</span><span class="token punctuation">[</span><span class="token punctuation">]</span> exceptions<span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">.</span> <span class="token punctuation">}</span></span>
<span class="line">    <span class="token keyword">public</span> <span class="token keyword">void</span> <span class="token function">visitEnd</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">.</span> <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>关键方法说明：</p><table><thead><tr><th>方法</th><th>触发时机</th><th>返回值</th></tr></thead><tbody><tr><td><code>visit()</code></td><td>类头信息（版本、访问标志、类名、父类、接口）</td><td><code>void</code></td></tr><tr><td><code>visitField()</code></td><td>每个字段</td><td><code>FieldVisitor</code>——继续访问该字段的注解等</td></tr><tr><td><code>visitMethod()</code></td><td>每个方法</td><td><code>MethodVisitor</code>——继续访问该方法体的字节码</td></tr><tr><td><code>visitEnd()</code></td><td>类解析结束</td><td><code>void</code></td></tr></tbody></table><p><strong>核心原则</strong>：当你重写 <code>visitMethod()</code> 时，必须返回一个 <code>MethodVisitor</code>（可以是父类的，也可以是你自己包装过的），否则该方法的方法体字节码就不会被访问。</p><h3 id="classwriter-——-生成字节码" tabindex="-1"><a class="header-anchor" href="#classwriter-——-生成字节码"><span>ClassWriter —— 生成字节码</span></a></h3><p><code>ClassWriter</code> 是 <code>ClassVisitor</code> 的子类，它把接收到的事件重新编码为字节码：</p><div class="language-java line-numbers-mode" data-highlighter="prismjs" data-ext="java"><pre><code><span class="line"><span class="token class-name">ClassWriter</span> cw <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">ClassWriter</span><span class="token punctuation">(</span><span class="token class-name">ClassWriter</span><span class="token punctuation">.</span><span class="token constant">COMPUTE_FRAMES</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// ... 让 ClassReader 通过 ClassVisitor 链向 cw 写入事件 ...</span></span>
<span class="line"><span class="token keyword">byte</span><span class="token punctuation">[</span><span class="token punctuation">]</span> modified <span class="token operator">=</span> cw<span class="token punctuation">.</span><span class="token function">toByteArray</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>构造参数控制 <code>ClassWriter</code> 的自动计算行为：</p><table><thead><tr><th>参数</th><th>含义</th></tr></thead><tbody><tr><td><code>0</code></td><td>不自动计算任何东西，你需要手动计算栈帧、局部变量和栈大小</td></tr><tr><td><code>ClassWriter.COMPUTE_MAXS</code></td><td>自动计算局部变量表最大槽数和操作数栈最大深度</td></tr><tr><td><code>ClassWriter.COMPUTE_FRAMES</code></td><td>自动计算栈帧映射（包含 <code>COMPUTE_MAXS</code> 的功能）</td></tr></tbody></table><blockquote><p><strong>推荐</strong>：大多数场景下使用 <code>COMPUTE_FRAMES</code>，让 ASM 自动处理栈帧。但有两个前提：(1) <code>COMPUTE_FRAMES</code> 实际生效要求 ASM API 版本 ≥ 5（即 <code>Opcodes.ASM5</code> 或以上），因为 JDK 8 引入了新的栈帧类型；(2) <code>ClassWriter</code> 的部分构造函数默认用 <code>ASM4</code>——<strong>即使你传了 <code>COMPUTE_FRAMES</code>，如果构造时不显式传版本常量，默认还是 ASM4，<code>COMPUTE_FRAMES</code> 的行为可能不符合预期</strong>。</p><p>安全写法：</p><div class="language-java line-numbers-mode" data-highlighter="prismjs" data-ext="java"><pre><code><span class="line"><span class="token comment">// 明确传入 ASM9（或与你项目 JDK 版本匹配的版本常量）</span></span>
<span class="line"><span class="token class-name">ClassWriter</span> cw <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">ClassWriter</span><span class="token punctuation">(</span><span class="token class-name">ClassWriter</span><span class="token punctuation">.</span><span class="token constant">COMPUTE_FRAMES</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// ClassWriter 无参构造默认 ASM4，建议显式传入版本常量：</span></span>
<span class="line"><span class="token comment">// ClassWriter cw = new ClassWriter(ClassWriter.COMPUTE_FRAMES, Opcodes.ASM9);</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>ASM 库 9.x 版本的实际行为取决于具体构造器重载，保险起见始终显式传入版本常量。</p></blockquote><h3 id="methodvisitor-——-访问方法体" tabindex="-1"><a class="header-anchor" href="#methodvisitor-——-访问方法体"><span>MethodVisitor —— 访问方法体</span></a></h3><p><code>MethodVisitor</code> 是真正操作字节码指令的地方。它定义了访问每一条指令的方法：</p><div class="language-java line-numbers-mode" data-highlighter="prismjs" data-ext="java"><pre><code><span class="line"><span class="token keyword">public</span> <span class="token keyword">abstract</span> <span class="token keyword">class</span> <span class="token class-name">MethodVisitor</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">public</span> <span class="token keyword">void</span> <span class="token function">visitCode</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">.</span> <span class="token punctuation">}</span>                          <span class="token comment">// 方法体开始</span></span>
<span class="line">    <span class="token keyword">public</span> <span class="token keyword">void</span> <span class="token function">visitInsn</span><span class="token punctuation">(</span><span class="token keyword">int</span> opcode<span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">.</span> <span class="token punctuation">}</span>               <span class="token comment">// 零操作数指令（如 return, aload_0）</span></span>
<span class="line">    <span class="token keyword">public</span> <span class="token keyword">void</span> <span class="token function">visitIntInsn</span><span class="token punctuation">(</span><span class="token keyword">int</span> opcode<span class="token punctuation">,</span> <span class="token keyword">int</span> operand<span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">.</span> <span class="token punctuation">}</span>  <span class="token comment">// 单操作数指令</span></span>
<span class="line">    <span class="token keyword">public</span> <span class="token keyword">void</span> <span class="token function">visitVarInsn</span><span class="token punctuation">(</span><span class="token keyword">int</span> opcode<span class="token punctuation">,</span> <span class="token keyword">int</span> varIndex<span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">.</span> <span class="token punctuation">}</span> <span class="token comment">// 局部变量指令</span></span>
<span class="line">    <span class="token keyword">public</span> <span class="token keyword">void</span> <span class="token function">visitFieldInsn</span><span class="token punctuation">(</span><span class="token keyword">int</span> opcode<span class="token punctuation">,</span> <span class="token class-name">String</span> owner<span class="token punctuation">,</span></span>
<span class="line">                               <span class="token class-name">String</span> name<span class="token punctuation">,</span> <span class="token class-name">String</span> desc<span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">.</span> <span class="token punctuation">}</span>  <span class="token comment">// 字段访问指令</span></span>
<span class="line">    <span class="token keyword">public</span> <span class="token keyword">void</span> <span class="token function">visitMethodInsn</span><span class="token punctuation">(</span><span class="token keyword">int</span> opcode<span class="token punctuation">,</span> <span class="token class-name">String</span> owner<span class="token punctuation">,</span></span>
<span class="line">                                <span class="token class-name">String</span> name<span class="token punctuation">,</span> <span class="token class-name">String</span> desc<span class="token punctuation">,</span></span>
<span class="line">                                <span class="token keyword">boolean</span> isInterface<span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">.</span> <span class="token punctuation">}</span>  <span class="token comment">// 方法调用指令</span></span>
<span class="line">    <span class="token keyword">public</span> <span class="token keyword">void</span> <span class="token function">visitLdcInsn</span><span class="token punctuation">(</span><span class="token class-name">Object</span> cst<span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">.</span> <span class="token punctuation">}</span>             <span class="token comment">// 加载常量指令</span></span>
<span class="line">    <span class="token keyword">public</span> <span class="token keyword">void</span> <span class="token function">visitJumpInsn</span><span class="token punctuation">(</span><span class="token keyword">int</span> opcode<span class="token punctuation">,</span> <span class="token class-name">Label</span> label<span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">.</span> <span class="token punctuation">}</span>  <span class="token comment">// 跳转指令</span></span>
<span class="line">    <span class="token keyword">public</span> <span class="token keyword">void</span> <span class="token function">visitLabel</span><span class="token punctuation">(</span><span class="token class-name">Label</span> label<span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">.</span> <span class="token punctuation">}</span>              <span class="token comment">// 标号</span></span>
<span class="line">    <span class="token keyword">public</span> <span class="token keyword">void</span> <span class="token function">visitFrame</span><span class="token punctuation">(</span><span class="token keyword">int</span> type<span class="token punctuation">,</span> <span class="token keyword">int</span> nLocal<span class="token punctuation">,</span> <span class="token class-name">Object</span><span class="token punctuation">[</span><span class="token punctuation">]</span> local<span class="token punctuation">,</span></span>
<span class="line">                           <span class="token keyword">int</span> nStack<span class="token punctuation">,</span> <span class="token class-name">Object</span><span class="token punctuation">[</span><span class="token punctuation">]</span> stack<span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">.</span> <span class="token punctuation">}</span>  <span class="token comment">// 栈帧</span></span>
<span class="line">    <span class="token keyword">public</span> <span class="token keyword">void</span> <span class="token function">visitMaxs</span><span class="token punctuation">(</span><span class="token keyword">int</span> maxStack<span class="token punctuation">,</span> <span class="token keyword">int</span> maxLocals<span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">.</span> <span class="token punctuation">}</span>   <span class="token comment">// 方法体结束</span></span>
<span class="line">    <span class="token keyword">public</span> <span class="token keyword">void</span> <span class="token function">visitEnd</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">.</span> <span class="token punctuation">}</span>                           <span class="token comment">// 方法访问结束</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>每一条 JVM 字节码指令都有对应的 <code>visitXxx()</code> 方法。例如：</p><ul><li><code>aload_0</code> → <code>visitVarInsn(ALOAD, 0)</code></li><li><code>invokevirtual #5</code> → <code>visitMethodInsn(INVOKEVIRTUAL, &quot;java/io/PrintStream&quot;, &quot;println&quot;, &quot;(Ljava/lang/String;)V&quot;, false)</code></li><li><code>return</code> → <code>visitInsn(RETURN)</code></li></ul><p>ASM 的操作码常量定义在 <code>Opcodes</code> 接口中，所有 Visitor 都实现了这个接口，所以可以直接使用 <code>ALOAD</code>、<code>INVOKEVIRTUAL</code>、<code>RETURN</code> 等常量。</p><blockquote><p><strong><code>isInterface</code> 参数</strong>：<code>visitMethodInsn</code> 的最后一个参数表示方法所属的 <code>owner</code> 是类（<code>false</code>）还是接口（<code>true</code>），例如 <code>INVOKEVIRTUAL</code> 调用 <code>PrintStream.println()</code> 时填 <code>false</code>（具体类），而 <code>INVOKEINTERFACE</code> 调用 <code>Runnable.run()</code> 时填 <code>true</code>。填错会导致 <code>VerifyError</code> 或 <code>ClassFormatError</code>。</p></blockquote><h2 id="三种典型场景" tabindex="-1"><a class="header-anchor" href="#三种典型场景"><span>三种典型场景</span></a></h2><p>下面通过三个完整的例子，展示 ASM 在不同场景下的用法。</p><h3 id="场景一-只读——提取类信息" tabindex="-1"><a class="header-anchor" href="#场景一-只读——提取类信息"><span>场景一：只读——提取类信息</span></a></h3><p>需求：获取一个类的所有方法名和参数列表。</p><div class="language-java line-numbers-mode" data-highlighter="prismjs" data-ext="java"><pre><code><span class="line"><span class="token keyword">import</span> <span class="token import"><span class="token namespace">org<span class="token punctuation">.</span>objectweb<span class="token punctuation">.</span>asm<span class="token punctuation">.</span></span><span class="token operator">*</span></span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">public</span> <span class="token keyword">class</span> <span class="token class-name">MethodInfoPrinter</span> <span class="token keyword">extends</span> <span class="token class-name">ClassVisitor</span> <span class="token punctuation">{</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">public</span> <span class="token class-name">MethodInfoPrinter</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">super</span><span class="token punctuation">(</span><span class="token class-name">Opcodes</span><span class="token punctuation">.</span><span class="token constant">ASM9</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token annotation punctuation">@Override</span></span>
<span class="line">    <span class="token keyword">public</span> <span class="token class-name">MethodVisitor</span> <span class="token function">visitMethod</span><span class="token punctuation">(</span><span class="token keyword">int</span> access<span class="token punctuation">,</span> <span class="token class-name">String</span> name<span class="token punctuation">,</span></span>
<span class="line">                                     <span class="token class-name">String</span> desc<span class="token punctuation">,</span> <span class="token class-name">String</span> signature<span class="token punctuation">,</span></span>
<span class="line">                                     <span class="token class-name">String</span><span class="token punctuation">[</span><span class="token punctuation">]</span> exceptions<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">println</span><span class="token punctuation">(</span><span class="token string">&quot;方法: &quot;</span> <span class="token operator">+</span> <span class="token function">accessDesc</span><span class="token punctuation">(</span>access<span class="token punctuation">)</span> <span class="token operator">+</span> <span class="token string">&quot; &quot;</span> <span class="token operator">+</span> name <span class="token operator">+</span> desc<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token keyword">return</span> <span class="token keyword">null</span><span class="token punctuation">;</span>  <span class="token comment">// 返回 null 表示不继续访问该方法体（不需要读字节码）</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">private</span> <span class="token class-name">String</span> <span class="token function">accessDesc</span><span class="token punctuation">(</span><span class="token keyword">int</span> access<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token punctuation">(</span>access <span class="token operator">&amp;</span> <span class="token class-name">Opcodes</span><span class="token punctuation">.</span><span class="token constant">ACC_PUBLIC</span><span class="token punctuation">)</span> <span class="token operator">!=</span> <span class="token number">0</span><span class="token punctuation">)</span> <span class="token keyword">return</span> <span class="token string">&quot;public&quot;</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token punctuation">(</span>access <span class="token operator">&amp;</span> <span class="token class-name">Opcodes</span><span class="token punctuation">.</span><span class="token constant">ACC_PRIVATE</span><span class="token punctuation">)</span> <span class="token operator">!=</span> <span class="token number">0</span><span class="token punctuation">)</span> <span class="token keyword">return</span> <span class="token string">&quot;private&quot;</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token punctuation">(</span>access <span class="token operator">&amp;</span> <span class="token class-name">Opcodes</span><span class="token punctuation">.</span><span class="token constant">ACC_PROTECTED</span><span class="token punctuation">)</span> <span class="token operator">!=</span> <span class="token number">0</span><span class="token punctuation">)</span> <span class="token keyword">return</span> <span class="token string">&quot;protected&quot;</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token keyword">return</span> <span class="token string">&quot;package-private&quot;</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token keyword">void</span> <span class="token function">main</span><span class="token punctuation">(</span><span class="token class-name">String</span><span class="token punctuation">[</span><span class="token punctuation">]</span> args<span class="token punctuation">)</span> <span class="token keyword">throws</span> <span class="token class-name">Exception</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token class-name">ClassReader</span> reader <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">ClassReader</span><span class="token punctuation">(</span><span class="token string">&quot;java.util.ArrayList&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token class-name">MethodInfoPrinter</span> printer <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">MethodInfoPrinter</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        reader<span class="token punctuation">.</span><span class="token function">accept</span><span class="token punctuation">(</span>printer<span class="token punctuation">,</span> <span class="token class-name">ClassReader</span><span class="token punctuation">.</span><span class="token constant">SKIP_CODE</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>输出示例：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code><span class="line">方法: public &lt;init&gt;()V</span>
<span class="line">方法: public &lt;init&gt;(I)V</span>
<span class="line">方法: public &lt;init&gt;(Ljava/util/Collection;)V</span>
<span class="line">方法: public add(Ljava/lang/Object;)Z</span>
<span class="line">方法: public get(I)Ljava/lang/Object;</span>
<span class="line">...</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>关键点：</p><ul><li><code>return null</code> 表示跳过该方法体的字节码，因为我们只关心方法签名</li><li><code>ClassReader.SKIP_CODE</code> 让解析器跳过字节码，进一步加快速度</li><li>不需要 <code>ClassWriter</code>，因为不修改任何东西</li></ul><h3 id="场景二-修改——给类添加方法" tabindex="-1"><a class="header-anchor" href="#场景二-修改——给类添加方法"><span>场景二：修改——给类添加方法</span></a></h3><p>需求：给一个已有类添加一个 <code>getVersion()</code> 方法，返回字符串 <code>&quot;1.0&quot;</code>。</p><div class="language-java line-numbers-mode" data-highlighter="prismjs" data-ext="java"><pre><code><span class="line"><span class="token keyword">public</span> <span class="token keyword">class</span> <span class="token class-name">AddMethodAdapter</span> <span class="token keyword">extends</span> <span class="token class-name">ClassVisitor</span> <span class="token punctuation">{</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">private</span> <span class="token class-name">String</span> className<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">public</span> <span class="token class-name">AddMethodAdapter</span><span class="token punctuation">(</span><span class="token class-name">ClassVisitor</span> cv<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">super</span><span class="token punctuation">(</span><span class="token class-name">Opcodes</span><span class="token punctuation">.</span><span class="token constant">ASM9</span><span class="token punctuation">,</span> cv<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token annotation punctuation">@Override</span></span>
<span class="line">    <span class="token keyword">public</span> <span class="token keyword">void</span> <span class="token function">visit</span><span class="token punctuation">(</span><span class="token keyword">int</span> version<span class="token punctuation">,</span> <span class="token keyword">int</span> access<span class="token punctuation">,</span> <span class="token class-name">String</span> name<span class="token punctuation">,</span></span>
<span class="line">                      <span class="token class-name">String</span> signature<span class="token punctuation">,</span> <span class="token class-name">String</span> superName<span class="token punctuation">,</span> <span class="token class-name">String</span><span class="token punctuation">[</span><span class="token punctuation">]</span> interfaces<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">this</span><span class="token punctuation">.</span>className <span class="token operator">=</span> name<span class="token punctuation">;</span></span>
<span class="line">        <span class="token keyword">super</span><span class="token punctuation">.</span><span class="token function">visit</span><span class="token punctuation">(</span>version<span class="token punctuation">,</span> access<span class="token punctuation">,</span> name<span class="token punctuation">,</span> signature<span class="token punctuation">,</span> superName<span class="token punctuation">,</span> interfaces<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token annotation punctuation">@Override</span></span>
<span class="line">    <span class="token keyword">public</span> <span class="token keyword">void</span> <span class="token function">visitEnd</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token comment">// 在类的末尾添加新方法</span></span>
<span class="line">        <span class="token class-name">MethodVisitor</span> mv <span class="token operator">=</span> cv<span class="token punctuation">.</span><span class="token function">visitMethod</span><span class="token punctuation">(</span></span>
<span class="line">            <span class="token class-name">Opcodes</span><span class="token punctuation">.</span><span class="token constant">ACC_PUBLIC</span><span class="token punctuation">,</span>          <span class="token comment">// 访问标志</span></span>
<span class="line">            <span class="token string">&quot;getVersion&quot;</span><span class="token punctuation">,</span>                <span class="token comment">// 方法名</span></span>
<span class="line">            <span class="token string">&quot;()Ljava/lang/String;&quot;</span><span class="token punctuation">,</span>      <span class="token comment">// 描述符：无参，返回 String</span></span>
<span class="line">            <span class="token keyword">null</span><span class="token punctuation">,</span>                        <span class="token comment">// 泛型签名</span></span>
<span class="line">            <span class="token keyword">null</span>                         <span class="token comment">// 异常列表</span></span>
<span class="line">        <span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        mv<span class="token punctuation">.</span><span class="token function">visitCode</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        mv<span class="token punctuation">.</span><span class="token function">visitLdcInsn</span><span class="token punctuation">(</span><span class="token string">&quot;1.0&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>                       <span class="token comment">// 将 &quot;1.0&quot; 压入栈</span></span>
<span class="line">        mv<span class="token punctuation">.</span><span class="token function">visitInsn</span><span class="token punctuation">(</span><span class="token class-name">Opcodes</span><span class="token punctuation">.</span><span class="token constant">ARETURN</span><span class="token punctuation">)</span><span class="token punctuation">;</span>                <span class="token comment">// 返回栈顶的 String</span></span>
<span class="line">        mv<span class="token punctuation">.</span><span class="token function">visitMaxs</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>                           <span class="token comment">// 最大栈深度=1，局部变量槽数=1</span></span>
<span class="line">        mv<span class="token punctuation">.</span><span class="token function">visitEnd</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">        <span class="token keyword">super</span><span class="token punctuation">.</span><span class="token function">visitEnd</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// 必须调用，让链上的后续 Visitor 也收到 visitEnd 事件</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>使用方式：</p><div class="language-java line-numbers-mode" data-highlighter="prismjs" data-ext="java"><pre><code><span class="line"><span class="token keyword">byte</span><span class="token punctuation">[</span><span class="token punctuation">]</span> classBytes <span class="token operator">=</span> <span class="token class-name">Files</span><span class="token punctuation">.</span><span class="token function">readAllBytes</span><span class="token punctuation">(</span><span class="token class-name">Path</span><span class="token punctuation">.</span><span class="token function">of</span><span class="token punctuation">(</span><span class="token string">&quot;MyClass.class&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token class-name">ClassReader</span> reader <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">ClassReader</span><span class="token punctuation">(</span>classBytes<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token class-name">ClassWriter</span> writer <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">ClassWriter</span><span class="token punctuation">(</span><span class="token class-name">ClassWriter</span><span class="token punctuation">.</span><span class="token constant">COMPUTE_FRAMES</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token class-name">AddMethodAdapter</span> adapter <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">AddMethodAdapter</span><span class="token punctuation">(</span>writer<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">reader<span class="token punctuation">.</span><span class="token function">accept</span><span class="token punctuation">(</span>adapter<span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">byte</span><span class="token punctuation">[</span><span class="token punctuation">]</span> modified <span class="token operator">=</span> writer<span class="token punctuation">.</span><span class="token function">toByteArray</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 写入文件或直接加载</span></span>
<span class="line"><span class="token class-name">Files</span><span class="token punctuation">.</span><span class="token function">write</span><span class="token punctuation">(</span><span class="token class-name">Path</span><span class="token punctuation">.</span><span class="token function">of</span><span class="token punctuation">(</span><span class="token string">&quot;MyClass.class&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span> modified<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>关键点：</p><ul><li>在 <code>visitEnd()</code> 中添加新方法，确保方法加在类的末尾，不会干扰已有方法</li><li>链式调用：<code>reader → adapter → writer</code>，每一层只处理自己关心的部分，其余透传给下一层</li><li>方法描述符 <code>()Ljava/lang/String;</code> 遵循 JVM 规范：括号内是参数类型，括号后是返回类型</li></ul><h3 id="场景三-生成——从零创建类" tabindex="-1"><a class="header-anchor" href="#场景三-生成——从零创建类"><span>场景三：生成——从零创建类</span></a></h3><p>需求：动态生成一个接口的实现类。</p><div class="language-java line-numbers-mode" data-highlighter="prismjs" data-ext="java"><pre><code><span class="line"><span class="token keyword">public</span> <span class="token keyword">class</span> <span class="token class-name">InterfaceImplGenerator</span> <span class="token punctuation">{</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token keyword">byte</span><span class="token punctuation">[</span><span class="token punctuation">]</span> <span class="token function">generateImpl</span><span class="token punctuation">(</span><span class="token class-name">String</span> interfaceName<span class="token punctuation">,</span> <span class="token class-name">String</span> implName<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token class-name">ClassWriter</span> cw <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">ClassWriter</span><span class="token punctuation">(</span><span class="token class-name">ClassWriter</span><span class="token punctuation">.</span><span class="token constant">COMPUTE_FRAMES</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        cw<span class="token punctuation">.</span><span class="token function">visit</span><span class="token punctuation">(</span></span>
<span class="line">            <span class="token class-name">Opcodes</span><span class="token punctuation">.</span><span class="token constant">V1_8</span><span class="token punctuation">,</span>                   <span class="token comment">// JDK 版本</span></span>
<span class="line">            <span class="token class-name">Opcodes</span><span class="token punctuation">.</span><span class="token constant">ACC_PUBLIC</span><span class="token punctuation">,</span>             <span class="token comment">// 访问标志</span></span>
<span class="line">            implName<span class="token punctuation">,</span>                       <span class="token comment">// 内部类名（用 / 分隔）</span></span>
<span class="line">            <span class="token keyword">null</span><span class="token punctuation">,</span>                           <span class="token comment">// 泛型签名</span></span>
<span class="line">            <span class="token string">&quot;java/lang/Object&quot;</span><span class="token punctuation">,</span>             <span class="token comment">// 父类</span></span>
<span class="line">            <span class="token keyword">new</span> <span class="token class-name">String</span><span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">{</span>interfaceName<span class="token punctuation">}</span>     <span class="token comment">// 实现的接口</span></span>
<span class="line">        <span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">        <span class="token comment">// 生成默认构造器</span></span>
<span class="line">        <span class="token class-name">MethodVisitor</span> mv <span class="token operator">=</span> cw<span class="token punctuation">.</span><span class="token function">visitMethod</span><span class="token punctuation">(</span></span>
<span class="line">            <span class="token class-name">Opcodes</span><span class="token punctuation">.</span><span class="token constant">ACC_PUBLIC</span><span class="token punctuation">,</span></span>
<span class="line">            <span class="token string">&quot;&lt;init&gt;&quot;</span><span class="token punctuation">,</span></span>
<span class="line">            <span class="token string">&quot;()V&quot;</span><span class="token punctuation">,</span></span>
<span class="line">            <span class="token keyword">null</span><span class="token punctuation">,</span> <span class="token keyword">null</span></span>
<span class="line">        <span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        mv<span class="token punctuation">.</span><span class="token function">visitCode</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        mv<span class="token punctuation">.</span><span class="token function">visitVarInsn</span><span class="token punctuation">(</span><span class="token class-name">Opcodes</span><span class="token punctuation">.</span><span class="token constant">ALOAD</span><span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">;</span>          <span class="token comment">// 加载 this</span></span>
<span class="line">        mv<span class="token punctuation">.</span><span class="token function">visitMethodInsn</span><span class="token punctuation">(</span><span class="token class-name">Opcodes</span><span class="token punctuation">.</span><span class="token constant">INVOKESPECIAL</span><span class="token punctuation">,</span></span>
<span class="line">            <span class="token string">&quot;java/lang/Object&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;&lt;init&gt;&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;()V&quot;</span><span class="token punctuation">,</span> <span class="token boolean">false</span><span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// 调用 super()</span></span>
<span class="line">        mv<span class="token punctuation">.</span><span class="token function">visitInsn</span><span class="token punctuation">(</span><span class="token class-name">Opcodes</span><span class="token punctuation">.</span><span class="token constant">RETURN</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        mv<span class="token punctuation">.</span><span class="token function">visitMaxs</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        mv<span class="token punctuation">.</span><span class="token function">visitEnd</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">        <span class="token comment">// 生成 sayHello() 方法</span></span>
<span class="line">        mv <span class="token operator">=</span> cw<span class="token punctuation">.</span><span class="token function">visitMethod</span><span class="token punctuation">(</span></span>
<span class="line">            <span class="token class-name">Opcodes</span><span class="token punctuation">.</span><span class="token constant">ACC_PUBLIC</span><span class="token punctuation">,</span></span>
<span class="line">            <span class="token string">&quot;sayHello&quot;</span><span class="token punctuation">,</span></span>
<span class="line">            <span class="token string">&quot;()Ljava/lang/String;&quot;</span><span class="token punctuation">,</span></span>
<span class="line">            <span class="token keyword">null</span><span class="token punctuation">,</span> <span class="token keyword">null</span></span>
<span class="line">        <span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        mv<span class="token punctuation">.</span><span class="token function">visitCode</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        mv<span class="token punctuation">.</span><span class="token function">visitLdcInsn</span><span class="token punctuation">(</span><span class="token string">&quot;Hello from generated class!&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        mv<span class="token punctuation">.</span><span class="token function">visitInsn</span><span class="token punctuation">(</span><span class="token class-name">Opcodes</span><span class="token punctuation">.</span><span class="token constant">ARETURN</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        mv<span class="token punctuation">.</span><span class="token function">visitMaxs</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        mv<span class="token punctuation">.</span><span class="token function">visitEnd</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">        cw<span class="token punctuation">.</span><span class="token function">visitEnd</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token keyword">return</span> cw<span class="token punctuation">.</span><span class="token function">toByteArray</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>注意这里的代码风格和场景二不同：场景二是<strong>包装模式</strong>（<code>ClassVisitor</code> 包装另一个 <code>ClassVisitor</code>），场景三是<strong>直接访问模式</strong>（直接调用 <code>ClassWriter</code> 的 <code>visitXxx()</code> 方法）。包装模式适合&quot;修改已有类&quot;，直接模式适合&quot;从零生成类&quot;。</p><h2 id="深入-修改方法体中的字节码" tabindex="-1"><a class="header-anchor" href="#深入-修改方法体中的字节码"><span>深入：修改方法体中的字节码</span></a></h2><p>前面场景二的例子是在类级别添加方法，但如果要修改<strong>已有方法内部的字节码指令</strong>，就需要在 <code>MethodVisitor</code> 层面做文章。</p><h3 id="经典例子-在方法入口和出口插入日志" tabindex="-1"><a class="header-anchor" href="#经典例子-在方法入口和出口插入日志"><span>经典例子：在方法入口和出口插入日志</span></a></h3><div class="language-java line-numbers-mode" data-highlighter="prismjs" data-ext="java"><pre><code><span class="line"><span class="token keyword">public</span> <span class="token keyword">class</span> <span class="token class-name">MethodLogAdapter</span> <span class="token keyword">extends</span> <span class="token class-name">ClassVisitor</span> <span class="token punctuation">{</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">private</span> <span class="token class-name">String</span> className<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">public</span> <span class="token class-name">MethodLogAdapter</span><span class="token punctuation">(</span><span class="token class-name">ClassVisitor</span> cv<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">super</span><span class="token punctuation">(</span><span class="token class-name">Opcodes</span><span class="token punctuation">.</span><span class="token constant">ASM9</span><span class="token punctuation">,</span> cv<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token annotation punctuation">@Override</span></span>
<span class="line">    <span class="token keyword">public</span> <span class="token keyword">void</span> <span class="token function">visit</span><span class="token punctuation">(</span><span class="token keyword">int</span> version<span class="token punctuation">,</span> <span class="token keyword">int</span> access<span class="token punctuation">,</span> <span class="token class-name">String</span> name<span class="token punctuation">,</span></span>
<span class="line">                      <span class="token class-name">String</span> signature<span class="token punctuation">,</span> <span class="token class-name">String</span> superName<span class="token punctuation">,</span> <span class="token class-name">String</span><span class="token punctuation">[</span><span class="token punctuation">]</span> interfaces<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">this</span><span class="token punctuation">.</span>className <span class="token operator">=</span> name<span class="token punctuation">;</span></span>
<span class="line">        <span class="token keyword">super</span><span class="token punctuation">.</span><span class="token function">visit</span><span class="token punctuation">(</span>version<span class="token punctuation">,</span> access<span class="token punctuation">,</span> name<span class="token punctuation">,</span> signature<span class="token punctuation">,</span> superName<span class="token punctuation">,</span> interfaces<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token annotation punctuation">@Override</span></span>
<span class="line">    <span class="token keyword">public</span> <span class="token class-name">MethodVisitor</span> <span class="token function">visitMethod</span><span class="token punctuation">(</span><span class="token keyword">int</span> access<span class="token punctuation">,</span> <span class="token class-name">String</span> name<span class="token punctuation">,</span></span>
<span class="line">                                     <span class="token class-name">String</span> desc<span class="token punctuation">,</span> <span class="token class-name">String</span> signature<span class="token punctuation">,</span></span>
<span class="line">                                     <span class="token class-name">String</span><span class="token punctuation">[</span><span class="token punctuation">]</span> exceptions<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token class-name">MethodVisitor</span> mv <span class="token operator">=</span> <span class="token keyword">super</span><span class="token punctuation">.</span><span class="token function">visitMethod</span><span class="token punctuation">(</span>access<span class="token punctuation">,</span> name<span class="token punctuation">,</span> desc<span class="token punctuation">,</span> signature<span class="token punctuation">,</span> exceptions<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token comment">// 跳过构造器和静态初始化块</span></span>
<span class="line">        <span class="token keyword">if</span> <span class="token punctuation">(</span>name<span class="token punctuation">.</span><span class="token function">equals</span><span class="token punctuation">(</span><span class="token string">&quot;&lt;init&gt;&quot;</span><span class="token punctuation">)</span> <span class="token operator">||</span> name<span class="token punctuation">.</span><span class="token function">equals</span><span class="token punctuation">(</span><span class="token string">&quot;&lt;clinit&gt;&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token keyword">return</span> mv<span class="token punctuation">;</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">        <span class="token comment">// 包装一个自定义的 MethodVisitor</span></span>
<span class="line">        <span class="token keyword">return</span> <span class="token keyword">new</span> <span class="token class-name">LogMethodVisitor</span><span class="token punctuation">(</span>mv<span class="token punctuation">,</span> className<span class="token punctuation">,</span> name<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token doc-comment comment">/**</span>
<span class="line">     * 自定义 MethodVisitor：在方法入口和每个 return 前插入日志</span>
<span class="line">     */</span></span>
<span class="line">    <span class="token keyword">static</span> <span class="token keyword">class</span> <span class="token class-name">LogMethodVisitor</span> <span class="token keyword">extends</span> <span class="token class-name">MethodVisitor</span> <span class="token punctuation">{</span></span>
<span class="line"></span>
<span class="line">        <span class="token keyword">private</span> <span class="token keyword">final</span> <span class="token class-name">String</span> className<span class="token punctuation">;</span></span>
<span class="line">        <span class="token keyword">private</span> <span class="token keyword">final</span> <span class="token class-name">String</span> methodName<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">        <span class="token keyword">public</span> <span class="token class-name">LogMethodVisitor</span><span class="token punctuation">(</span><span class="token class-name">MethodVisitor</span> mv<span class="token punctuation">,</span> <span class="token class-name">String</span> className<span class="token punctuation">,</span> <span class="token class-name">String</span> methodName<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token keyword">super</span><span class="token punctuation">(</span><span class="token class-name">Opcodes</span><span class="token punctuation">.</span><span class="token constant">ASM9</span><span class="token punctuation">,</span> mv<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">            <span class="token keyword">this</span><span class="token punctuation">.</span>className <span class="token operator">=</span> className<span class="token punctuation">;</span></span>
<span class="line">            <span class="token keyword">this</span><span class="token punctuation">.</span>methodName <span class="token operator">=</span> methodName<span class="token punctuation">;</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">        <span class="token annotation punctuation">@Override</span></span>
<span class="line">        <span class="token keyword">public</span> <span class="token keyword">void</span> <span class="token function">visitCode</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token comment">// 在方法入口插入日志</span></span>
<span class="line">            <span class="token comment">// System.out.println(&quot;Enter: &quot; + className + &quot;.&quot; + methodName);</span></span>
<span class="line">            mv<span class="token punctuation">.</span><span class="token function">visitFieldInsn</span><span class="token punctuation">(</span><span class="token class-name">Opcodes</span><span class="token punctuation">.</span><span class="token constant">GETSTATIC</span><span class="token punctuation">,</span></span>
<span class="line">                <span class="token string">&quot;java/lang/System&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;out&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;Ljava/io/PrintStream;&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">            mv<span class="token punctuation">.</span><span class="token function">visitLdcInsn</span><span class="token punctuation">(</span><span class="token string">&quot;Enter: &quot;</span> <span class="token operator">+</span> className <span class="token operator">+</span> <span class="token string">&quot;.&quot;</span> <span class="token operator">+</span> methodName<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">            mv<span class="token punctuation">.</span><span class="token function">visitMethodInsn</span><span class="token punctuation">(</span><span class="token class-name">Opcodes</span><span class="token punctuation">.</span><span class="token constant">INVOKEVIRTUAL</span><span class="token punctuation">,</span></span>
<span class="line">                <span class="token string">&quot;java/io/PrintStream&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;println&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;(Ljava/lang/String;)V&quot;</span><span class="token punctuation">,</span> <span class="token boolean">false</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">            <span class="token keyword">super</span><span class="token punctuation">.</span><span class="token function">visitCode</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">        <span class="token annotation punctuation">@Override</span></span>
<span class="line">        <span class="token keyword">public</span> <span class="token keyword">void</span> <span class="token function">visitInsn</span><span class="token punctuation">(</span><span class="token keyword">int</span> opcode<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token comment">// 在每个 return 指令前插入日志</span></span>
<span class="line">            <span class="token keyword">if</span> <span class="token punctuation">(</span>opcode <span class="token operator">&gt;=</span> <span class="token class-name">Opcodes</span><span class="token punctuation">.</span><span class="token constant">IRETURN</span> <span class="token operator">&amp;&amp;</span> opcode <span class="token operator">&lt;=</span> <span class="token class-name">Opcodes</span><span class="token punctuation">.</span><span class="token constant">RETURN</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">                mv<span class="token punctuation">.</span><span class="token function">visitFieldInsn</span><span class="token punctuation">(</span><span class="token class-name">Opcodes</span><span class="token punctuation">.</span><span class="token constant">GETSTATIC</span><span class="token punctuation">,</span></span>
<span class="line">                    <span class="token string">&quot;java/lang/System&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;out&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;Ljava/io/PrintStream;&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">                mv<span class="token punctuation">.</span><span class="token function">visitLdcInsn</span><span class="token punctuation">(</span><span class="token string">&quot;Exit: &quot;</span> <span class="token operator">+</span> className <span class="token operator">+</span> <span class="token string">&quot;.&quot;</span> <span class="token operator">+</span> methodName<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">                mv<span class="token punctuation">.</span><span class="token function">visitMethodInsn</span><span class="token punctuation">(</span><span class="token class-name">Opcodes</span><span class="token punctuation">.</span><span class="token constant">INVOKEVIRTUAL</span><span class="token punctuation">,</span></span>
<span class="line">                    <span class="token string">&quot;java/io/PrintStream&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;println&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;(Ljava/lang/String;)V&quot;</span><span class="token punctuation">,</span> <span class="token boolean">false</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">            <span class="token punctuation">}</span></span>
<span class="line">            <span class="token keyword">super</span><span class="token punctuation">.</span><span class="token function">visitInsn</span><span class="token punctuation">(</span>opcode<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这个例子展示了 ASM 的核心用法模式：</p><ol><li>在 <code>visitMethod()</code> 中返回一个包装过的 <code>MethodVisitor</code></li><li>在感兴趣的方法（<code>visitCode()</code>、<code>visitInsn()</code> 等）中插入额外的字节码指令</li><li>其余方法透传给父类处理</li></ol><h3 id="注意事项" tabindex="-1"><a class="header-anchor" href="#注意事项"><span>注意事项</span></a></h3><ol><li><p><strong>栈帧问题</strong>：插入指令后，栈帧映射会失效。使用 <code>ClassWriter.COMPUTE_FRAMES</code> 让 ASM 自动重新计算是最简单的方案。</p></li><li><p><strong>构造器的特殊处理</strong>：构造器的第一条指令必须是 <code>super()</code> 调用（<code>invokespecial</code> 调用父类 <code>&lt;init&gt;</code>）。如果要在构造器中插入代码，必须放在 <code>super()</code> 调用之后。通常的做法是跳过构造器，或者用更复杂的方式定位 <code>super()</code> 调用之后的位置。</p></li><li><p><strong>局部变量索引</strong>：插入新代码时如果需要使用局部变量，必须了解当前方法已有的局部变量分布，避免索引冲突。</p></li></ol><h2 id="asm-版本常量与兼容性" tabindex="-1"><a class="header-anchor" href="#asm-版本常量与兼容性"><span>ASM 版本常量与兼容性</span></a></h2><p>ASM 提供了一个 <code>Opcodes</code> 接口，其中定义了版本常量：</p><table><thead><tr><th>常量</th><th>数值</th><th>支持的 JDK 字节码</th></tr></thead><tbody><tr><td><code>ASM4</code></td><td>4 &lt;&lt; 16</td><td>JDK 6 / 7</td></tr><tr><td><code>ASM5</code></td><td>5 &lt;&lt; 16</td><td>JDK 8</td></tr><tr><td><code>ASM6</code></td><td>6 &lt;&lt; 16</td><td>JDK 9</td></tr><tr><td><code>ASM7</code></td><td>7 &lt;&lt; 16</td><td>JDK 11</td></tr><tr><td><code>ASM8</code></td><td>8 &lt;&lt; 16</td><td>JDK 14</td></tr><tr><td><code>ASM9</code></td><td>9 &lt;&lt; 16</td><td>JDK 17+</td></tr></tbody></table><p>这个版本常量在构造 <code>ClassVisitor</code>、<code>ClassWriter</code> 时需要传入：</p><div class="language-java line-numbers-mode" data-highlighter="prismjs" data-ext="java"><pre><code><span class="line"><span class="token comment">// 如果项目用的是 JDK 8，应该用 ASM5 及以上</span></span>
<span class="line"><span class="token class-name">ClassWriter</span> cw <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">ClassWriter</span><span class="token punctuation">(</span><span class="token class-name">ClassWriter</span><span class="token punctuation">.</span><span class="token constant">COMPUTE_FRAMES</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// 等价于 new ClassWriter(Opcodes.ASM4) —— 但 ASM4 不认识接口 default 方法！</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>常见踩坑点</strong>：很多框架在底层硬编码了 <code>ASM4</code>，而项目已经升级到 JDK 8+。当代码中调用了接口的 default 方法（如 <code>Comparator.reversed()</code>）时，编译器会生成 <code>invokespecial</code> 指向接口的字节码。ASM4 遇到这种指令会抛出 <code>IllegalArgumentException</code>，表现为&quot;功能静默丢失&quot;。</p><blockquote><p>注意：接口 static 方法（如 <code>Comparator.comparing()</code>）使用 <code>invokestatic</code> 指令，ASM4 对这种指令<strong>不会报错</strong>。因为 <code>invokestatic</code> 只检查目标方法是否是静态的，不关心 owner 是类还是接口。真正触发 ASM4 报错的是 <code>invokespecial</code> 指向接口 default 方法这一情况。</p></blockquote>`,81)),n("p",null,[s[20]||(s[20]=a("关于这个问题的详细排查过程和解决方案，参见 ")),t(l,{to:"/java/advanced/bytecode/asm-bytecode-compatibility.html"},{default:p(()=>s[19]||(s[19]=[a("这个线上故障案例")])),_:1,__:[19]}),s[21]||(s[21]=a("。"))]),s[24]||(s[24]=c('<h2 id="框架中的-asm-应用" tabindex="-1"><a class="header-anchor" href="#框架中的-asm-应用"><span>框架中的 ASM 应用</span></a></h2><p>了解 ASM 之后，你会发现很多框架的底层实现原理变得清晰了：</p><table><thead><tr><th>框架</th><th>ASM 的用途</th></tr></thead><tbody><tr><td><strong>Spring</strong></td><td>AOP 代理、<code>@Configuration</code> 类增强、<code>@Transactional</code> 代理</td></tr><tr><td><strong>MyBatis</strong></td><td>读取接口方法参数名（用于 <code>#{param}</code> 映射）</td></tr><tr><td><strong>Hibernate</strong></td><td>实体类字节码增强（懒加载代理）</td></tr><tr><td><strong>Lombok</strong></td><td>注解处理器中生成 <code>getter</code>/<code>setter</code>/<code>builder</code> 等方法</td></tr><tr><td><strong>Mockito</strong></td><td>动态生成 mock 对象的实现类</td></tr><tr><td><strong>Jackson</strong></td><td>序列化/反序列化器的高性能实现</td></tr><tr><td><strong>Kotlin 编译器</strong></td><td>生成兼容 JVM 的字节码</td></tr></tbody></table><p>以 MyBatis 为例，当你写 <code>@Param(&quot;userId&quot;) Long userId</code> 时，MyBatis 在运行时需要用 ASM 读取接口的字节码，从中提取参数名。如果 MyBatis 依赖的 ASM 版本过低，就无法正确读取 JDK 8+ 编译的类的参数名——这就是经典的 <strong>&quot;MyBatis 参数名绑定时好时坏&quot;</strong> 问题的根因之一。</p><h2 id="总结" tabindex="-1"><a class="header-anchor" href="#总结"><span>总结</span></a></h2><ul><li><strong>ASM 是字节码级操作框架</strong>，速度极快但学习曲线陡峭。大多数开发者不直接使用它，而是通过 Spring、MyBatis 等框架间接依赖它。</li><li><strong>核心模型是事件驱动 + Visitor 链</strong>：<code>ClassReader</code> 解析类文件产生事件 → <code>ClassVisitor</code> 链处理事件 → <code>ClassWriter</code> 编码回字节码。</li><li><strong>三种典型场景</strong>：只读（只有 reader + visitor）、修改（reader + visitor + writer 串联）、生成（直接 writer）。</li><li><strong>修改方法体</strong>需要在 <code>MethodVisitor</code> 层面包装，在指令前后插入新指令，注意栈帧和构造器的特殊约束。</li><li><strong>版本常量</strong>很重要：JDK 版本升级后，ASM 版本常量也需要同步升级，否则遇到新语言特性（如接口 default 方法）会直接报错。</li></ul><p>ASM 的底层性决定了它不太适合&quot;直接手写&quot;来开发业务功能，但理解它的工作原理，能让你在排查框架底层问题、理解字节码增强机制时多一个有力的分析工具。</p>',7))])}const g=i(r,[["render",v]]),h=JSON.parse('{"path":"/java/advanced/bytecode/asm-introduction.html","title":"ASM 字节码框架入门","lang":"zh-CN","frontmatter":{},"git":{"updatedTime":1788403565000,"contributors":[{"name":"zhaomy","username":"zhaomy","email":"3036190149@qq.com","commits":1,"url":"https://github.com/zhaomy"}],"changelog":[{"hash":"641f31523568107b5458347bc8a45f74515bf54e","time":1788403565000,"email":"3036190149@qq.com","author":"zhaomy","message":"docs(java): 新增 JVM 字节码与 ASM 教程"}]},"filePathRelative":"java/advanced/bytecode/asm-introduction.md","excerpt":"\\n\\n<h2>什么是 ASM？</h2>\\n<p>ASM 是一个轻量级的 Java 字节码操作框架。它能够直接以二进制形式读取、修改和生成 <code>.class</code> 文件，而无需依赖 <code>javac</code> 编译器。</p>\\n<p>它的核心定位是<strong>底层、快速、精简</strong>：</p>\\n<table>\\n<thead>\\n<tr>\\n<th>维度</th>\\n<th>说明</th>\\n</tr>\\n</thead>\\n<tbody>\\n<tr>\\n<td>定位</td>\\n<td>字节码级别的操作库，不依赖源码</td>\\n</tr>\\n<tr>\\n<td>性能</td>\\n<td>极快，采用事件驱动模型，解析时只做一次遍历</td>\\n</tr>\\n<tr>\\n<td>体积</td>\\n<td>核心 jar 仅约 100KB</td>\\n</tr>\\n<tr>\\n<td>学习曲线</td>\\n<td>陡峭——需要理解字节码指令、类文件结构</td>\\n</tr>\\n</tbody>\\n</table>"}');export{g as comp,h as data};
